 "hebrew": "עַד אָנָה יְהֹוָה תִּשְׁכָּחֵנִי נֶצַח עַד אָנָה תַּסְתִּיר אֶת פָּנֶיךָ מִמֶּנִּי׃",
 "transliteration": "'adanah Adonai tishekajeni netsaj 'adanah tasetir etpaneyja mimeni",
 "spanish": "¿Hasta cuándo pondré consejos en mi alma, Con ansiedad en mi corazón cada día? ¿Hasta cuándo será enaltecido mi enemigo sobre mí?"
