 "hebrew": "אָמַרְתְּ לַיהֹוָה אֲדֹנָי אָתָּה טוֹבָתִי בַּל עָלֶיךָ׃",
 "transliteration": "amarete layhovah adonay atah toovati bal'aleyja",
