 "hebrew": "שְׁמַע עַמִּי וְאָעִידָה בָּךְ יִשְׂרָאֵל אִם תִּשְׁמַע לִי׃",
 "transliteration": "shema' 'ami vea'idah baje iserael imtishema'li",
 "spanish": "No habrá en ti dios ajeno, Ni te encorvarás á dios extraño."
