 "hebrew": "וּפָקַדְתִּי בְשֵׁבֶט פִּשְׁעָם וּבִנְגָעִים עֲוֺנָם׃",
 "transliteration": "ufakadeti veshevet pishe'am uvinega'im 'avnam",
 "spanish": "Mas no quitaré de él mi misericordia, Ni falsearé mi verdad."
