 "hebrew": "יָגוֹדּוּ עַל נֶפֶשׁ צַדִּיק וְדָם נָקִי יַרְשִׁיעוּ׃",
 "transliteration": "yagoodu 'alnefesh tsadik vedam naki yareshi'v",
 "spanish": "Pónense en corros contra la vida del justo, Y condenan la sangre inocente."
