 "transliteration": "'ameja nedavut beyoom jeyleja behadereykodesh merejem mishejar leja tal yaleduteyja",
 "spanish": "Tu pueblo serálo de buena voluntad en el día de tu poder, En la hermosura de la santidad: desde el seno de la aurora, Tienes tú el rocío de tu juventud."
