 "transliteration": "nisheba' Adonai velo inajem atahjohen le'oolam 'aldiverati malekitsedek",
 "spanish": "Juró Jehová, y no se arrepentirá: Tú eres sacerdote para siempre Según el orden de Melchîsedech."
