 "transliteration": "anah Adonai kiani 'avedeja ani'avedeja benamateja pitajeta lemooseray",
 "spanish": "Oh Jehová, que yo soy tu siervo, Yo tu siervo, hijo de tu sierva: Rompiste mis prisiones."
