 "hebrew": "לֹא אָמוּת כִּי אֶחְיֶה וַאֲסַפֵּר מַעֲשֵׂי יָהּ׃",
 "transliteration": "loamut kiejeyeh vaasaper ma'asey yah",
 "spanish": "No moriré, sino que viviré, Y contaré las obras de JAH."
